 "content": "def transform(grid):
    """Match same-sized rectangular frames, copy their interior pattern, and
    discard frame outliers whose dimensions do not match the repeated group.
    """
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    frames = []
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, _ in cells)
        r1 = max(r for r, _ in cells)
        c0 = min(c for _, c in cells)
        c1 = max(c for _, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        if not all(grid[r0][c] == color and grid[r1][c] == color
                   for c in range(c0, c1 + 1)):
            continue
        if not all(grid[r][c0] == color and grid[r][c1] == color
                   for r in range(r0, r1 + 1)):
            continue
        pattern = [[grid[r][c] == color for c in range(c0 + 1, c1)]
                   for r in range(r0 + 1, r1)]
        frames.append((color, r0, r1, c0, c1, pattern,
                       sum(sum(row) for row in pattern)))

    if not frames:
        return out
    groups = {}
    for frame in frames:
        color, r0, r1, c0, c1, pattern, count = frame
        groups.setdefault((r1 - r0 + 1, c1 - c0 + 1), []).append(frame)
    # The repeated rectangle dimensions identify the working set.
    active = max(groups.values(), key=len)
    if len(active) < 2:
        return out
    active_ids = {frame[0] for frame in active}
    # Unmatched framed objects are distractors and are removed entirely.
    for color, r0, r1, c0, c1, pattern, count in frames:
        if color not in active_ids:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    if out[r][c] == color:
                        out[r][c] = 0
    sources = [frame for frame in active if frame[6] > 0]
    if sources:
        source = max(sources, key=lambda frame: frame[6])
        template = source[5]
        for color, r0, r1, c0, c1, pattern, count in active:
            if count == 0:
                for dr, row in enumerate(template):
                    for dc, filled in enumerate(row):
                        out[r0 + 1 + dr][c0 + 1 + dc] = color if filled else 0
    return out


